class Solution:
    def isValid(self, s: str) -> bool:
        stack = []

        # Iterate over each character in the string
        for char in s:
            if char == "(" or char == "[" or char == "{":
                # If it's an opening bracket, push to stack
                stack.append(char)
            else:
                # If it's a closing bracket
                if not stack:  # Check if stack is empty (unmatched closing bracket)
                    return False

                top_element = stack.pop()

                # Check if the popped element matches with current closing bracket
                if (top_element == '(' and char != ')') or \
                   (top_element == '[' and char != ']') or \
                   (top_element == '{' and char != '}'):
                    return False

        # After iterating through all characters, check if stack is empty
        return len(stack) == 0

