String toStringVisiting(Digraph graph) {
  List<String> visited = [];
  void visit(Node node) {
    if (visited.contains(node)) return;
    visited.add(node);

    for (Node neighbor in graph.outgoingEdges[node]!) {
      visit(neighbor);
    }
  }

  // Start from an arbitrary node and traverse the graph
  Node startNode = null;
  for (var entry in graph.nodes.entries) {
    startNode = entry.key;
    break;
  }

  if (startNode != null) {
    visit(startNode);
  }

  // Convert nodes to strings and join them
  String result = '';
  for (int i = 0; i < visited.length; i++) {
    result += '${i + 1}: ${visited[i].toString()}';
    if (i < visited.length - 1) result += ', ';
  }

  return 'Digraph: $result';
}

