class Solution{
public:
    /***
     * Given a string and an integer 'n', find the longest substring that can be rotated left by n characters, such that the resulting rotation is equal to the original substring. Return the length of this longest substring. If no valid substring exists (i.e., for all substrings of length ≥2, rotating them by any amount does not yield themselves), return -1.
     * 
     * Constraints:
     * 2 <= s.length() <= 5000
     * The string consists only of lowercase English letters.
     * 0 <= n <= len(s) - 1
     */
    int stringSearchSingle(string &s,int n){
        // Special case: if the entire string can be rotated back to itself after n shifts, then it's valid.
        if(rotate(s.begin(), s.begin()+n, s.end()) == s){
            return s.size(); // Entire string qualifies as the longest valid substring
        }

        // Initialize result with maximum possible value (-inf)
        int ans = INT_MIN;
        int m = s.size();

        // Check every starting position i from 0 to m-1
        for(int i=0; i<m; ++i){
            // Try all ending positions j where substring [i,j] has at least length 2
            for(int j=i+2; j<=m; ++j){
                // Extract current candidate substring
                string temp = s.substr(i, j-i);

                // Rotate the substring left by n times
                rotate(temp.begin(), temp.begin()+n%temp.size(), temp.end());

                // Compare rotated version with original
                if(temp != s.substr(i, j-i)){
                    continue; // Skip invalid rotations — try next substring
                } else {
                    // Valid rotation found — update answer if longer than previous best
                    ans = max(ans, j-i);
                }
            }
        }

        // Return -1 if no valid substring was found during iteration
        return ans==-INT_MIN ? -1 : ans;
    }
};

