class Solution {
    public void Solve(char[][] board) {
        int m = board.Length;
        if (m == 0) return;

        int n = board[0].Length;

        // Mark all 'O's that are connected to the border with a temporary character.
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if ((i == 0 || i == m - 1 || j == 0 || j == n - 1) && board[i][j] == 'O') {
                    DFS(i, j);
                }
            }
        }

        // Flip remaining 'O' regions surrounded by 'X'.
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (board[i][j] == 'O') {
                    board[i][j] = 'X';
                } else if (board[i][j] == '#') {
                    board[i][j] = 'O';
                }
            }
        }
    }

    private void DFS(int row, int col) {
        int m = board.Length;
        int n = board[row].Length;

        if (row < 0 || row >= m || col < 0 || col >= n || board[row][col] != 'O') {
            return;
        }

        board[row][col] = '#';

        DFS(row + 1, col);
        DFS(row - 1, col);
        DFS(row, col + 1);
        DFS(row, col - 1);
    }
}
