# Python code to implement Shunting Yard Algorithm
def precedence(op):
    if op == '+' or op == '-':
        return 1
    elif op == '*' or op == '/' or op == '^':
        return 2
    else:
        return -1

def apply_operator(operators, values):
    right = values.pop()
    left = values.pop()
    operator = operators.pop()

    if operator == '+':
        result = left + right
    elif operator == '-':
        result = left - right
    elif operator == '*':
        result = left * right
    elif operator == '/':
        result = left / right
    elif operator == '^':
        result = left ** right

    values.append(result)

def shunting_yard(expression):
    output_queue = []
    operator_stack = []

    for token in expression.split():
        # If the current token is a number (operand), add it to the output queue.
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            output_queue.append(token)

        # If the current token is an opening parenthesis '(', push it onto the operator stack.
        elif token == '(':
            operator_stack.append('(')

        # If the current token is a closing parenthesis ')', pop all operators from the stack 
        # until you encounter an opening parenthesis '(' and then discard both parentheses.
        elif token == ')':
            while operator_stack[-1] != '(':
                operator = operator_stack.pop()
                output_queue.append(operator)
            operator_stack.pop() # Discard the opening parenthesis

        # If the current token is an operator (+,-,*,/,^). Pop any operators with equal 
        # or greater precedence than this one from the stack and append them to the output queue. 
        # Then push this operator onto the stack.
        else:
            while len(operator_stack) > 0 and operator_stack[-1] != '(' \
                    and precedence(operator_stack[-1]) >= precedence(token):
                output_queue.append(operator_stack.pop())

            operator_stack.append(token)

    # After processing all tokens, pop any remaining operators from the stack and append 
    # them to the output queue. This ensures that we don't forget any operators that weren't enclosed in parentheses.
    while len(operator_stack) > 0:
        operator = operator_stack.pop()
        output_queue.append(operator)

    return output_queue

